{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.all_skugroups_size_ratio_repeat as with all_sku as ( select sku_group, case when sku_group in (select sku_group from snitch_db.maplemonk.final_output_eoq where repeat = \'yes\') then \'yes\' else \'no\' end as eoq_flag, ifnull(sum(case when SIZE = \'XS\' OR SIZE = \'28\' then total_inventory end),0) as xs_inv, ifnull(sum(case WHEN SIZE = \'S\' OR SIZE = \'30\' then total_inventory end),0) as s_inv, ifnull(sum(case WHEN SIZE = \'M\' OR SIZE = \'32\' then total_inventory end),0) as m_inv, ifnull(sum(case WHEN SIZE = \'L\' OR SIZE = \'34\' then total_inventory end),0) as l_inv, ifnull(sum(case WHEN SIZE = \'XL\' OR SIZE = \'36\' then total_inventory end),0) as xl_inv, ifnull(sum(case when SIZE IN (\'XXL\', \'XXl\', \'2XL\', \'38\') then total_inventory end),0) as xxl_inv from snitch_db.maplemonk.cut_size_analysis where date = current_date-1 group by 1 ), sales as ( select sku_group, ifnull(sum(case when SIZE = \'XS\' OR SIZE = \'28\' then gross_quantity end),0) as xs_quant, ifnull(sum(case WHEN SIZE = \'S\' OR SIZE = \'30\' then gross_quantity end),0) as s_quant, ifnull(sum(case WHEN SIZE = \'M\' OR SIZE = \'32\' then gross_quantity end),0) as m_quant, ifnull(sum(case WHEN SIZE = \'L\' OR SIZE = \'34\' then gross_quantity end),0) as l_quant, ifnull(sum(case WHEN SIZE = \'XL\' OR SIZE = \'36\' then gross_quantity end),0) as xl_quant, ifnull(sum(case when SIZE IN (\'XXL\', \'XXl\', \'2XL\', \'38\') then gross_quantity end),0) as xxl_quant from snitch_db.maplemonk.horizontal_sales_categories where sku_group in (select sku_group from all_sku where eoq_flag = \'no\') group by 1 ), size_tag as ( select a.*, b.size_tag from sales a left join snitch_db.maplemonk.sku_group_xs_without_xs_eoq b on a.sku_group = b.sku_group ), least_quant as ( select *, CASE WHEN size_tag = \'with_xs_with_xxl\' THEN CAST( ARRAY_MIN(ARRAY_CONSTRUCT_COMPACT( NULLIF(xs_quant, 0), NULLIF(s_quant, 0), NULLIF(m_quant, 0), NULLIF(l_quant, 0), NULLIF(xl_quant, 0), NULLIF(xxl_quant, 0) )) AS INTEGER) WHEN size_tag = \'without_xs_without_xxl\' THEN CAST( ARRAY_MIN(ARRAY_CONSTRUCT_COMPACT( NULLIF(s_quant, 0), NULLIF(m_quant, 0), NULLIF(l_quant, 0), NULLIF(xl_quant, 0) )) AS INTEGER) WHEN size_tag = \'with_xs_without_xxl\' THEN CAST( ARRAY_MIN(ARRAY_CONSTRUCT_COMPACT( NULLIF(xs_quant, 0), NULLIF(s_quant, 0), NULLIF(m_quant, 0), NULLIF(l_quant, 0), NULLIF(xl_quant, 0) )) AS INTEGER) WHEN size_tag = \'without_xs_with_xxl\' THEN CAST( ARRAY_MIN(ARRAY_CONSTRUCT_COMPACT( NULLIF(s_quant, 0), NULLIF(m_quant, 0), NULLIF(l_quant, 0), NULLIF(xl_quant, 0), NULLIF(xxl_quant, 0) )) AS INTEGER) END AS least_quant from size_tag ), sizepreratio as ( select *, floor(xs_quant/least_quant) as xs_ratio, floor(s_quant/least_quant)+1 as s_ratio, floor(m_quant/least_quant)+1 as m_ratio, floor(l_quant/least_quant)+1 as l_ratio, floor(xl_quant/least_quant)+1 as xl_ratio, floor(xxl_quant/least_quant) as xxl_ratio, floor(xs_quant/least_quant)+floor(s_quant/least_quant)+1+floor(m_quant/least_quant)+1+floor(l_quant/least_quant)+1+floor(xl_quant/least_quant)+1+floor(xxl_quant/least_quant) as total_ratio from least_quant ), order_size as ( select *, (1000*(xs_ratio/(total_ratio)))::int as xs_order_quant, (1000*(s_ratio/(total_ratio)))::int as s_order_quant, (1000*(m_ratio/(total_ratio)))::int as m_order_quant, (1000*(l_ratio/(total_ratio)))::int as l_order_quant, (1000*(xl_ratio/(total_ratio)))::int as xl_order_quant, (1000*(xxl_ratio/(total_ratio)))::int as xxl_order_quant from sizepreratio ), ros as ( select sku_group, (((ifnull(sum(case when SIZE = \'XS\' OR SIZE = \'28\' then gross_quantity end),0)/60)*0.3)*90)::int as xs_sold, (((ifnull(sum(case WHEN SIZE = \'S\' OR SIZE = \'30\' then gross_quantity end),0)/60))*90)::int as s_ros, (((ifnull(sum(case WHEN SIZE = \'M\' OR SIZE = \'32\' then gross_quantity end),0)/60))*90)::int as m_ros, (((ifnull(sum(case WHEN SIZE = \'L\' OR SIZE = \'34\' then gross_quantity end),0)/60))*90)::int as l_ros, (((ifnull(sum(case WHEN SIZE = \'XL\' OR SIZE = \'36\' then gross_quantity end),0)/60))*90)::int as xl_ros, (((ifnull(sum(case when SIZE IN (\'XXL\', \'XXl\', \'2XL\', \'38\') then gross_quantity end),0)/60)*0.3)*90)::int as xxl_ros from snitch_db.maplemonk.horizontal_sales_categories where sku_group in (select sku_group from all_sku where eoq_flag = \'no\') and date >= current_date-60 group by 1 ), inv_left as ( select a.*, greatest(xs_inv-xs_sold,0) as xs_inv_left, greatest(s_inv-xs_sold,0) as s_inv_left, greatest(m_inv-xs_sold,0) as m_inv_left, greatest(l_inv-xs_sold,0) as l_inv_left, greatest(xl_inv-xs_sold,0) as xl_inv_left, greatest(xxl_inv-xs_sold,0) as xxl_inv_left from all_sku a left join ros b on a.sku_group = b.sku_group ), pre_main as ( select a.*, greatest(xs_order_quant-xs_inv_left,0) as xs_op, greatest(s_order_quant-s_inv_left,0) as s_op, greatest(m_order_quant-m_inv_left,0) as m_op, greatest(l_order_quant-l_inv_left,0) as l_op, greatest(xl_order_quant-xl_inv_left,0) as xl_op, greatest(xxl_order_quant-xxl_inv_left,0) as xxl_op from order_size a left join inv_left b on a.sku_group = b.sku_group ), least_quant_op as ( select *, CASE WHEN size_tag = \'with_xs_with_xxl\' THEN CAST( ARRAY_MIN(ARRAY_CONSTRUCT_COMPACT( NULLIF(xs_op, 0), NULLIF(s_op, 0), NULLIF(m_op, 0), NULLIF(l_op, 0), NULLIF(xl_op, 0), NULLIF(xxl_op, 0) )) AS INTEGER) WHEN size_tag = \'without_xs_without_xxl\' THEN CAST( ARRAY_MIN(ARRAY_CONSTRUCT_COMPACT( NULLIF(s_op, 0), NULLIF(m_op, 0), NULLIF(l_op, 0), NULLIF(xl_op, 0) )) AS INTEGER) WHEN size_tag = \'with_xs_without_xxl\' THEN CAST( ARRAY_MIN(ARRAY_CONSTRUCT_COMPACT( NULLIF(xs_op, 0), NULLIF(s_op, 0), NULLIF(m_op, 0), NULLIF(l_op, 0), NULLIF(xl_op, 0) )) AS INTEGER) WHEN size_tag = \'without_xs_with_xxl\' THEN CAST( ARRAY_MIN(ARRAY_CONSTRUCT_COMPACT( NULLIF(s_op, 0), NULLIF(m_op, 0), NULLIF(l_op, 0), NULLIF(xl_op, 0), NULLIF(xxl_op, 0) )) AS INTEGER) END AS least_quant_op from pre_main ), main as ( select *, floor(xs_op/least_quant_op) as xs_ratio_op, floor(s_op/least_quant_op)+1 as s_ratio_op, floor(m_op/least_quant_op)+1 as m_ratio_op, floor(l_op/least_quant_op)+1 as l_ratio_op, floor(xl_op/least_quant_op)+1 as xl_ratio_op, floor(xxl_op/least_quant_op) as xxl_ratio_op from least_quant_op where least_quant is not null and xs_op is not null ) select sku_group, concat(xs_ratio_op,\' : \',s_ratio_op,\' : \',m_ratio_op,\' : \',l_ratio_op,\' : \',xl_ratio_op,\' : \',xxl_ratio_op) as size_ratio from main",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            